template <typename Derived>
struct PolicyBase {
    void invoke() {
        // Compile-time resolution (Static Dispatch)
        static_cast<Derived*>(this)->executeImpl();
    }
};

struct OptimizedPolicy : PolicyBase<OptimizedPolicy> {
    void executeImpl() { /* Fast path code */ }
};

struct DefaultPolicy : PolicyBase<DefaultPolicy> {
    void executeImpl() { /* Standard path code */ }
};

